//! The seeded-defect corpus (GEO-023): every committed model is checked, every seeded
//! model must be found by the check that owns its class, and no clean model may raise
//! a blocking finding. The models are generated by `integrations/cad/faris_corpus.py`;
//! `corpus.json` lists them with the sha256 of every file.

use super::integrity::{self, Config};
use super::model::Model;
use super::overlap;
use super::par::Ctl;
use super::*;
use crate::jobs::Cancellation;
use faris_model::design::load_facets;
use std::collections::BTreeSet;

fn corpus_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/corpus")
}

#[derive(Deserialize)]
struct Index {
    models: Vec<Entry>,
}

#[derive(Deserialize)]
struct Entry {
    id: String,
    class: Option<String>,
    kind: String,
    subject: Option<String>,
    expected_requirements: Vec<String>,
    chord_m: f64,
    files: BTreeMap<String, String>,
    #[serde(default)]
    design_check: Option<DesignCheck>,
    #[serde(default)]
    local_run: Option<serde_json::Value>,
    /// GEO-032 as the CAD kernel measured it when the corpus was generated.
    #[serde(default)]
    deviation: Option<RecordedDeviation>,
    /// The overlap that was built into a CAD-level model, from its analytic dimensions.
    #[serde(default)]
    seeded_overlap: Option<SeededOverlap>,
    /// Each solid's CAD volume as the kernel measured it, by solid id (clean models).
    #[serde(default)]
    cad_volumes_m3: BTreeMap<String, f64>,
    base: String,
}

#[derive(Deserialize)]
struct SeededOverlap {
    pair: [usize; 2],
    fraction_of_smaller: f64,
    smaller_solid_volume_m3: f64,
    common_volume_m3: f64,
}

#[derive(Deserialize)]
struct RecordedDeviation {
    solids: Vec<RecordedSolid>,
}

#[derive(Deserialize)]
struct RecordedSolid {
    solid_id: String,
    max_distance_m: f64,
    complete: bool,
}

#[derive(Deserialize)]
struct DesignCheck {
    fails_at: usize,
}

fn index() -> Index {
    serde_json::from_slice(&std::fs::read(corpus_dir().join("corpus.json")).unwrap()).unwrap()
}

/// The candidate pairs of an unimprinted model, as the mesh search finds them.
fn candidates_of(entry: &Entry) -> Vec<overlap::Candidate> {
    let dir = corpus_dir();
    let bin = std::fs::read(dir.join(format!("{}.facets.bin", entry.id))).unwrap();
    let json = std::fs::read(dir.join(format!("{}.facets.json", entry.id))).unwrap();
    let loaded = load_facets(&bin, &json).unwrap();
    let model = Model::new(&loaded.facets).unwrap();
    let cancel = Cancellation::default();
    let progress = |_: &str, _: usize, _: usize| {};
    let ctl = Ctl::new(&cancel, &progress, 2);
    overlap::candidate_pairs(&model, entry.chord_m, 7, &ctl).unwrap()
}

/// FARIS's blocking requirement ids for one geometry model, and whether the candidate-pair
/// search flags a pair (for unimprinted models).
fn verdict(entry: &Entry) -> (BTreeSet<String>, usize) {
    let dir = corpus_dir();
    let bin = std::fs::read(dir.join(format!("{}.facets.bin", entry.id))).unwrap();
    let json = std::fs::read(dir.join(format!("{}.facets.json", entry.id))).unwrap();
    let loaded = load_facets(&bin, &json).unwrap();
    let labels: Vec<String> = loaded
        .manifest
        .volumes
        .iter()
        .map(|v| {
            v.material_tag
                .as_deref()
                .and_then(|t| t.strip_prefix("mat:"))
                .unwrap_or("?")
                .to_string()
        })
        .collect();
    let model = Model::new(&loaded.facets).unwrap();
    let cancel = Cancellation::default();
    let progress = |_: &str, _: usize, _: usize| {};
    let ctl = Ctl::new(&cancel, &progress, 2);
    let mut config = Config::new(entry.chord_m, 7);
    config.samples = 20_000;
    config.chords = 2_000;
    let mut result = integrity::check_integrity(&model, &labels, &config, &ctl).unwrap();
    if let Some(recorded) = &entry.deviation {
        let deviations: Vec<integrity::SolidDeviation> = recorded
            .solids
            .iter()
            .map(|s| integrity::SolidDeviation {
                solid_id: &s.solid_id,
                max_distance_m: s.max_distance_m,
                at_m: None,
                complete: s.complete,
            })
            .collect();
        let extra = integrity::thickness_misrepresented(&result.record.volumes, &deviations);
        result.findings.extend(extra);
    }
    if std::env::var("FARIS_CORPUS_DEBUG").is_ok() {
        for f in result.findings.iter().filter(|f| f.blocks()) {
            println!("{}: {:?} {} | {}", entry.id, f.requirement, f.item, f.why);
        }
    }
    let found = result
        .findings
        .iter()
        .filter(|f| f.blocks())
        .map(|f| f.requirement.clone().unwrap_or_default())
        .collect();
    let candidates = if entry.subject.as_deref() == Some("unimprinted") {
        overlap::candidate_pairs(&model, entry.chord_m, 7, &ctl)
            .unwrap()
            .len()
    } else {
        0
    };
    (found, candidates)
}

struct Recorded(StepInspection);

impl Backends for Recorded {
    fn inspect_step(&self, _: &Path, _: Option<LengthUnit>) -> Result<InspectOutcome, DesignError> {
        Ok(InspectOutcome {
            inspection: self.0.clone(),
            helper_sha256: "0".repeat(64),
            reader: ReaderStamp::python(),
            elapsed_seconds: 0.0,
        })
    }
    fn audit_materials(&self, _: &[AuditMaterial]) -> Result<AuditOutcome, DesignError> {
        Ok(AuditOutcome::NotEvaluated {
            why: "not used by the corpus".into(),
            next_step: String::new(),
        })
    }
}

fn design_fails_at(entry: &Entry) -> Option<u8> {
    let dir = corpus_dir();
    let inspection = StepInspection::from_bytes(
        &std::fs::read(dir.join(format!("{}.inspect.json", entry.id))).unwrap(),
    )
    .unwrap();
    let report = check_design(
        &dir.join(format!("{}.design.json", entry.id)),
        &Recorded(inspection),
    )
    .unwrap();
    report
        .checks
        .iter()
        .find(|c| c.status == CheckStatus::Fail)
        .map(|c| c.check)
}

// Verifies: GEO-023
#[test]
fn the_committed_files_are_the_files_the_generator_hashed() {
    let dir = corpus_dir();
    for entry in index().models {
        for (name, digest) in &entry.files {
            let bytes = std::fs::read(dir.join(name)).unwrap();
            assert_eq!(&sha256_hex(&bytes), digest, "{name}: edited by hand?");
        }
    }
}

// Verifies: GEO-023
#[test]
fn the_corpus_has_the_required_size_and_classes() {
    let index = index();
    let seeded: Vec<&Entry> = index.models.iter().filter(|m| m.kind == "seeded").collect();
    let clean = index.models.iter().filter(|m| m.kind == "clean").count();
    let classes: BTreeSet<&str> = seeded.iter().filter_map(|m| m.class.as_deref()).collect();
    assert!(seeded.len() >= 20, "{} seeded models", seeded.len());
    assert!(clean >= 20, "{clean} clean models");
    assert_eq!(classes.len(), 12, "{classes:?}");
}

// Verifies: GEO-023, GEO-020, GEO-021, GEO-022
#[test]
fn every_seeded_geometry_model_is_found_and_no_clean_model_raises_an_alarm() {
    let index = index();
    let mut detected = 0;
    let mut seeded = 0;
    let mut false_alarms = 0;
    let mut clean = 0;
    let mut missed = Vec::new();
    let mut alarms = Vec::new();
    let mut verdicts = BTreeMap::new();
    for entry in &index.models {
        match (entry.subject.as_deref(), entry.kind.as_str()) {
            (Some("design"), _) => continue,
            (None, _) => {
                // The CAD kernel could not mesh the model at all, which the conversion reports
                // as a failure (GEO-012). The recorded local run must say so.
                seeded += 1;
                let run = entry.local_run.as_ref().expect("local run recorded");
                let failed = run["convert"]["exit_code"] != serde_json::json!(0);
                if failed {
                    detected += 1;
                } else {
                    missed.push(entry.id.clone());
                }
            }
            (Some(_), "clean") => {
                clean += 1;
                let (found, _) = verdict(entry);
                verdicts.insert(entry.id.clone(), found.iter().cloned().collect::<Vec<_>>());
                if !found.is_empty() {
                    false_alarms += 1;
                    alarms.push((entry.id.clone(), found));
                }
            }
            (Some(_), _) => {
                seeded += 1;
                let (found, candidates) = verdict(entry);
                verdicts.insert(entry.id.clone(), found.iter().cloned().collect::<Vec<_>>());
                let hit = entry
                    .expected_requirements
                    .iter()
                    .any(|r| found.contains(r));
                let overlap_candidate = entry.class.as_deref() != Some("overlap") || candidates > 0;
                if hit && overlap_candidate {
                    detected += 1;
                } else {
                    missed.push(format!("{} found {found:?}", entry.id));
                }
            }
        }
    }
    println!(
        "corpus geometry: detected {detected}/{seeded} seeded, false alarms {false_alarms}/{clean} clean"
    );
    if let Ok(path) = std::env::var("FARIS_CORPUS_VERDICTS") {
        std::fs::write(path, serde_json::to_string_pretty(&verdicts).unwrap()).unwrap();
    }
    println!("alarms: {alarms:#?}");
    assert!(missed.is_empty(), "missed: {missed:#?}");
    assert!(alarms.is_empty(), "false alarms: {alarms:#?}");
    assert!(false_alarms * 100 <= clean, "false alarm rate above 1 %");
}

// Verifies: GEO-023, GEO-011
#[test]
fn the_design_level_defects_fail_at_the_check_that_owns_them() {
    for entry in index()
        .models
        .iter()
        .filter(|m| m.subject.as_deref() == Some("design"))
    {
        let expected = entry.design_check.as_ref().unwrap().fails_at;
        assert_eq!(
            design_fails_at(entry),
            Some(expected as u8),
            "{} ({:?})",
            entry.id,
            entry.class
        );
    }
}

// Verifies: GEO-021
#[test]
fn seeded_overlaps_down_to_one_part_in_ten_thousand_are_found_by_the_recorded_boolean() {
    let mut judged = BTreeSet::new();
    for entry in index().models.iter().filter(|m| m.seeded_overlap.is_some()) {
        let seeded = entry.seeded_overlap.as_ref().unwrap();
        let run = entry.local_run.as_ref().expect("local run recorded");
        let results: Vec<overlap::BooleanResult> =
            serde_json::from_value(run["booleans"]["pairs"].clone()).unwrap();
        let volumes: Vec<f64> = serde_json::from_value(run["solid_volumes_m3"].clone()).unwrap();
        let labels: Vec<String> = (0..volumes.len()).map(|i| format!("solid-{i}")).collect();
        let candidates = candidates_of(entry);
        let (records, findings) =
            overlap::boolean_findings(&candidates, &results, &volumes, &labels);
        let [a, b] = seeded.pair;
        let overlaps: Vec<&overlap::PairRecord> =
            records.iter().filter(|r| r.verdict == "overlap").collect();
        assert_eq!(overlaps.len(), 1, "{}: {records:#?}", entry.id);
        assert_eq!(
            (&overlaps[0].a, &overlaps[0].b),
            (&labels[a], &labels[b]),
            "{}",
            entry.id
        );
        assert!(
            findings.iter().all(|f| f.waivable && f.blocks()),
            "{}",
            entry.id
        );
        // The exact boolean measures what was built in, to well inside 1e-6 of it.
        let measured = overlaps[0].common_volume_m3.unwrap();
        assert!(
            (measured / seeded.common_volume_m3 - 1.0).abs() < 1.0e-6,
            "{}: measured {measured:e} against seeded {:e}",
            entry.id,
            seeded.common_volume_m3
        );
        let smaller = overlaps[0].smaller_solid_volume_m3;
        assert!(
            (smaller / seeded.smaller_solid_volume_m3 - 1.0).abs() < 1.0e-6,
            "{}",
            entry.id
        );
        assert!(
            (measured / smaller / seeded.fraction_of_smaller - 1.0).abs() < 1.0e-6,
            "{}",
            entry.id
        );
        judged.insert(seeded.fraction_of_smaller.to_bits());
    }
    // 1e-4 (the GEO-021 target) and 1e-5 (a decade below it), on more than one base.
    assert!(judged.contains(&1.0e-4_f64.to_bits()) && judged.contains(&1.0e-5_f64.to_bits()));
}

// Verifies: GEO-012, GEO-030
#[test]
fn the_volume_gate_replays_on_the_recorded_conversions_of_the_clean_models() {
    let dir = corpus_dir();
    let mut judged = BTreeMap::<String, (usize, usize)>::new();
    for entry in index().models.iter().filter(|m| m.kind == "clean") {
        let bin = std::fs::read(dir.join(format!("{}.facets.bin", entry.id))).unwrap();
        let json = std::fs::read(dir.join(format!("{}.facets.json", entry.id))).unwrap();
        let loaded = load_facets(&bin, &json).unwrap();
        let model = Model::new(&loaded.facets).unwrap();
        let stats = binding::volume_stats(&model.mesh, &loaded.facets, &loaded.manifest);
        let rows: Vec<binding::BindingRow> = stats
            .iter()
            .map(|v| {
                let id = v
                    .material_tag
                    .as_deref()
                    .unwrap()
                    .strip_prefix("mat:")
                    .unwrap();
                let cad = entry.cad_volumes_m3[id];
                binding::BindingRow {
                    volume: v.index,
                    global_id: v.global_id,
                    material_tag: v.material_tag.clone(),
                    solid_id: Some(id.to_string()),
                    faceted_volume_m3: v.faceted_volume_m3,
                    cad_volume_m3: Some(cad),
                    volume_relative_difference: Some(v.faceted_volume_m3 / cad - 1.0),
                    centroid_distance_m: None,
                    normalised_distance: None,
                    second_best_solid_id: None,
                    second_best_normalised_distance: None,
                }
            })
            .collect();
        assert_eq!(rows.len(), entry.cad_volumes_m3.len(), "{}", entry.id);
        let (gate, findings) = binding::volume_gate(&rows, entry.chord_m, false);
        let exceeded = gate
            .solids
            .iter()
            .filter(|s| s.verdict == "EXCEEDED")
            .count();
        assert_eq!(findings.len(), exceeded, "{}", entry.id);
        assert!(findings.iter().all(|f| f.blocks() && !f.waivable));
        let tally = judged.entry(entry.base.clone()).or_default();
        tally.0 += gate.solids.len();
        tally.1 += exceeded;
    }
    // The boxes are planar and the port base is cylinders at a 0.1 rad deviation: every cell
    // is within 0.1 % (worst port plug -0.0414 %). The torus fixtures are faceted at 0.5 rad on
    // purpose, to keep the files small, and are 1.4 % to 1.6 % low: the gate must refuse them.
    assert_eq!(judged["boxes"], (24, 0));
    assert_eq!(judged["port"], (24, 0));
    assert_eq!(judged["tori"], (24, 24));
}
